        if(kind.equals("exams")){addText(f,"没考的科目留空；满分可按试卷修改。",12,MUTED,false);for(int i=0;i<Data.SUBJECTS.length;i++){String s=Data.SUBJECTS[i];JSONObject scores=o.optJSONObject("scores"),v=scores==null?null:scores.optJSONObject(s);LinearLayout line=row(),left=col(),right=col();line.addView(left,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,-2,1);rp.leftMargin=dp(10);line.addView(right,rp);f.addView(line);scoreInputs.put(s,new EditText[]{input(left,s+"成绩",v==null?"":Data.number(v.optDouble("score")),true),input(right,"满分",v==null?Data.number(Data.subjectConfig(store.profile(),s).optDouble("max",100)):Data.number(v.optDouble("max")),true)});}rank=input(f,"名次（可选，空白表示不记录）",o.optInt("rank")>0?""+o.optInt("rank"):"",true);gradeRank=input(f,"年级名次（可选）",o.optInt("gradeRank")>0?""+o.optInt("gradeRank"):"",true);}
        if(kind.equals("study")||kind.equals("tasks"))mins=input(f,kind.equals("study")?"实际学习分钟数":"预计分钟数",String.valueOf(o.optInt("minutes",30)),true);
        if(kind.equals("study"))focus=spinner(f,"专注自评 · 1 较低 / 5 很好",new String[]{"1","2","3","4","5"},String.valueOf(o.optInt("focus",3)));
        if(kind.equals("tasks")){actual=input(f,"实际分钟数（未开始填 0）",String.valueOf(o.optInt("actualMinutes",0)),true);status=spinner(f,"状态",Data.STATUS,o.optString("status",o.optBoolean("done")?"已完成":"未开始"));}
        if(kind.equals("tasks"))priority=spinner(f,"优先级",new String[]{"1 · 优先处理","2 · 正常安排","3 · 有空再做"},new String[]{"1 · 优先处理","2 · 正常安排","3 · 有空再做"}[o.optInt("priority",2)-1]);
        if(kind.equals("weak")){cause=spinner(f,"主要错因",Data.CAUSES,o.optString("cause",Data.CAUSES[0]));mastery=spinner(f,"掌握状态",Data.MASTERY,o.optString("mastery",Data.MASTERY[0]));}
        EditText note=kind.equals("tasks")?null:input(f,"备注（可选）",o.optString("note"),false);
        final EditText fr=rank,fgr=gradeRank,fm=mins,fa=actual;final Spinner ff=focus,fp=priority,fc=cause,fma=mastery,fet=examType,fst=status;
        formDialog(existing==null?"添加记录":"编辑记录",f,"保存",()->{
            Data.set(o,"date",val(date));Data.set(o,"title",val(title));if(subject!=null)Data.set(o,"subject",subject.getSelectedItem().toString());if(note!=null)Data.set(o,"note",val(note));
            if(kind.equals("exams")){JSONObject scores=new JSONObject();for(Map.Entry<String,EditText[]> e:scoreInputs.entrySet()){EditText[] v=e.getValue();if(!val(v[0]).isEmpty())Data.set(scores,e.getKey(),Data.obj("score",doubleVal(v[0],"成绩"),"max",doubleVal(v[1],"满分")));}Data.set(o,"scores",scores);Data.set(o,"rank",val(fr).isEmpty()?0:intVal(fr,"班级名次"));Data.set(o,"gradeRank",val(fgr).isEmpty()?0:intVal(fgr,"年级名次"));Data.set(o,"examType",fet.getSelectedItem().toString());}
            if(fm!=null)Data.set(o,"minutes",intVal(fm,"分钟数"));if(ff!=null)Data.set(o,"focus",ff.getSelectedItemPosition()+1);
            if(fp!=null){Data.set(o,"priority",fp.getSelectedItemPosition()+1);Data.set(o,"status",fst.getSelectedItem().toString());Data.set(o,"actualMinutes",intVal(fa,"实际时间"));Data.set(o,"done",fst.getSelectedItemPosition()==2);Data.set(o,"completedAt",fst.getSelectedItemPosition()==2?(o.optString("completedAt").isEmpty()?Data.today():o.optString("completedAt")):"");}
            if(fc!=null){Data.set(o,"cause",fc.getSelectedItem().toString());String next=fma.getSelectedItem().toString();if(!next.equals(o.optString("mastery"))){JSONArray history=o.optJSONArray("history");if(history==null)history=new JSONArray();history.put(Data.obj("date",Data.today(),"from",o.optString("mastery","未掌握"),"to",next));Data.set(o,"history",history);}Data.set(o,"mastery",next);}boolean timer=o.optBoolean("fromTimer");o.remove("fromTimer");store.put(kind,o);if(timer)clearTimer();toast("已保存到手机");
        });
