        usageCard(body);LinearLayout backup=card(body);addText(backup,"数据备份",18,INK,true);addText(backup,"JSON 包含全部学习数据、报告、目标和必要设置；不包含 API Key。卸载会删除本地数据，请先备份。",12,MUTED,false);addButton(backup,"导出完整备份",true,()->{try{exportFile("StudyPersonal-"+Data.today()+".json","application/json",store.backup().toString(2));}catch(Exception e){error(e);}});addButton(backup,"导入备份",false,()->{if(busy.get()){toast("请先结束当前 AI 请求");return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,101);}catch(Exception e){error(e);}});File recovery=new File(getFilesDir(),"before-restore.json");if(recovery.exists())addButton(backup,"导出上次覆盖前的安全备份",false,()->{try(FileInputStream in=new FileInputStream(recovery)){exportFile("StudyPersonal-recovery.json","application/json",AiClient.read(in,10*1024*1024));}catch(Exception e){error(e);}});
